import{_ as r,I as n,c as i,o,ag as t,J as s}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"Understand the pieces","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/javascript/orientation.md","filePath":"applied-ai/javascript/orientation.md"}'),d={name:"applied-ai/javascript/orientation.md"};function c(l,e,p,h,u,m){const a=n("MermaidDiagram");return o(),i("div",null,[e[0]||(e[0]=t('<h1 id="_0-understand-the-pieces" tabindex="-1">Understand the pieces <a class="header-anchor" href="#_0-understand-the-pieces" aria-label="Permalink to “Understand the pieces”">​</a></h1><p>An AI application is ordinary software with a model inside it. You still write the UI, validation, storage, error handling and tests. The model supplies a useful but fallible operation: generating text, selecting a proposed tool call, or representing text for search.</p><p>You need functions, arrays/objects, modules, JSON, promises and <code>async</code>/<code>await</code>. If those are unfamiliar, use the <a href="./../../node-js/prerequisites-and-boundaries.html">Node prerequisites</a>. You do not need Python, calculus or model-training experience to begin.</p><h2 id="give-each-word-a-concrete-meaning" tabindex="-1"><span class="hub-section-number">1 </span>Give each word a concrete meaning <a class="header-anchor" href="#give-each-word-a-concrete-meaning" aria-label="Permalink to “1 Give each word a concrete meaning”">​</a></h2><p>Imagine asking a notes assistant, “How do I cancel a request?”</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this project</th></tr></thead><tbody><tr><td>Model</td><td>The remote service that generates a possible answer</td></tr><tr><td>Prompt</td><td>Task instructions and input sent to that service</td></tr><tr><td>Context</td><td>Relevant messages or note excerpts included with the request</td></tr><tr><td>Token</td><td>A model-specific piece of input/output used for context limits and often billing; not exactly a word</td></tr><tr><td>Chat history</td><td>Previous conversation messages stored by the application or a configured provider feature</td></tr><tr><td>Structured output</td><td>A result shaped as fields your application can validate</td></tr><tr><td>Tool</td><td>A function the application may execute after checking a proposed call</td></tr><tr><td>Workflow</td><td>A sequence such as validate→retrieve→answer→check</td></tr><tr><td>Agent</td><td>A system in which a model selects some next actions within application limits</td></tr><tr><td>RAG</td><td>Retrieve relevant source material, then use it as evidence for generation</td></tr><tr><td>MCP</td><td>A standard interface through which a host connects to a server&#39;s tools, resources and prompts</td></tr></tbody></table><p>A model can generate a plausible answer without reading your notes. That does not mean it searched them. Your application must retrieve the notes and provide them. Similarly, “I renamed the note” is text until an authorized function actually performs the write.</p><h2 id="trace-one-request" tabindex="-1"><span class="hub-section-number">2 </span>Trace one request <a class="header-anchor" href="#trace-one-request" aria-label="Permalink to “2 Trace one request”">​</a></h2>',8)),s(a,{"encoded-source":"flowchart%20LR%0A%20%20U%5BYou%5D%20--%3E%20B%5BBrowser%20chat%5D%0A%20%20B%20--%3E%20S%5BYour%20Node%20server%5D%0A%20%20S%20--%3E%20M%5BModel%20provider%5D%0A%20%20M%20--%3E%20S%0A%20%20S%20--%3E%20B%0A%20%20S%20--%3E%20N%5BSelected%20notes%20or%20checked%20tools%5D"}),e[1]||(e[1]=t('<p>The browser sends a question to <strong>your server</strong>. Your server validates it, supplies instructions/history, calls a model if configured, and returns a usable result. The provider key stays on the server. Your service, the model provider and an MCP server are separate roles even when all appear in one diagram.</p><h2 id="start-with-fewer-moving-parts" tabindex="-1"><span class="hub-section-number">3 </span>Start with fewer moving parts <a class="header-anchor" href="#start-with-fewer-moving-parts" aria-label="Permalink to “3 Start with fewer moving parts”">​</a></h2><p>We begin with JavaScript modules and Node&#39;s built-in HTTP server. You can see what a request does without learning a new framework at the same time. The browser example uses plain DOM code; the chatbot lesson explains how the same contract fits React. Introduce TypeScript after you can trace the data: types help development, but runtime validation still protects external input.</p><p>Offline mode returns an intentionally obvious simulation. It proves that your console or UI can reach a function and display its result. A live mode uses the Responses REST endpoint through <code>fetch</code>; you can later replace that small adapter with the official SDK. No API call occurs merely by reading or running the mock example.</p><h2 id="predict-before-running" tabindex="-1"><span class="hub-section-number">4 </span>Predict before running <a class="header-anchor" href="#predict-before-running" aria-label="Permalink to “4 Predict before running”">​</a></h2><p>For “What is my name?”, predict the answer if no prior name was supplied. Then imagine a previous message, “My name is Alex.” What would the application need to include? The model does not read a JavaScript variable just because it exists in your server.</p><p><strong>Your exercise:</strong> draw the request path and mark where you would put a key, history and a private notes database. Explain why retrieved text is evidence, not permission to execute a command inside it.</p><p><strong>Ready to continue:</strong> you can explain the pieces without naming a framework, and distinguish using an assistant to write code from building an application that calls a model. <a href="./first-call.html">Next: first request</a>.</p>',8))])}const v=r(d,[["render",c]]);export{g as __pageData,v as default};
